{
  "title": "The Clockwork Rescue",
  "gate_token": "WfAOHPOFZRlLm-GdKS4otA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a ruined city map.",
      "visual_description": "A shattered royal city under a grey sky. Mara leans over a stone table, unrolling a torn parchment map while wind stirs old royal banners on a distant tower.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of dangers ahead.",
      "visual_description": "In a dim alley, the Oracle Lamp floats beside Mara, its single flame-eye flickering as it speaks in a low hiss.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Glass Diver arrives through a broken window.",
      "visual_description": "A shattered shop window ripples like water. The Glass Diver steps through, his diving helmet gleaming with reflected fragments of the ruined street.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Mara greets the Glass Diver at the rendezvous.",
      "visual_description": "Mara and the Glass Diver meet beneath a collapsed archway. Tin Fox scurries from the shadows and sniffs at the Diver's coat.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Tin Fox scouts ahead near the castle gates.",
      "visual_description": "The massive iron castle gates loom, dented and ajar. Tin Fox creeps between rusted bars, blue eyes scanning the courtyard beyond.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle Lamp illuminates a cursed tower.",
      "visual_description": "A twisted tower leans over the city walls, its stones weeping black moss. The Oracle Lamp's glow reveals faint runes carved into the base.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Mara negotiates with the Sleeping Tax Collector.",
      "visual_description": "In a dusty ledger room, the Sleeping Tax Collector snores on a pile of stamped papers. Mara shakes him gently, but he only rolls over, clutching his ledger pillow.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver swims through a magic door.",
      "visual_description": "A ornate door covered in glowing glyphs. The Glass Diver presses his hand to the surface, which turns liquid, and he steps through into a mirrored corridor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox reports back to Mara and Oracle Lamp.",
      "visual_description": "Tin Fox clicks across cobblestones to where Mara holds the Oracle Lamp. The fox's tail winds down as it emits a series of metallic chirps.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Mara reads the Oracle Lamp's vision of a dragon rumor.",
      "visual_description": "The Oracle Lamp's flame grows tall, projecting a smoky image of a winged shadow over the city. Mara watches with narrowed eyes.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver emerges from the magic door into a throne room.",
      "visual_description": "A collapsed throne room under a dome of cracked stained glass. The Glass Diver stands amid fallen banners, his helmet reflecting a thousand colored shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Sleeping Tax Collector wakes briefly to stamp a permit.",
      "visual_description": "Mara shoves a blank paper under the sleeping official's nose. He half-opens one eye, stamps it without looking, then resumes snoring.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols march through a square below.",
      "visual_description": "From a high window, Mara and Tin Fox watch a line of faceless armored figures clank across a flagstone square, their footsteps echoing.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle Lamp leads the group through a secret tunnel.",
      "visual_description": "A narrow, damp tunnel beneath the city. The Oracle Lamp floats ahead, its flame casting dancing shadows on the brick walls.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Glass Diver rescues a trapped townsfolk (a frightened figure).",
      "visual_description": "In a cell with a barred window, a trembling figure in rags huddles. The Glass Diver turns the window's surface to liquid and reaches through, offering a hand.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group reassembles near the escape bridge.",
      "visual_description": "At the foot of a stone bridge that spans a chasm, the group gathers: Mara, Glass Diver, Oracle Lamp, Tin Fox, and the rescued figure. The bridge is cracked but passable.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols block the bridge exit.",
      "visual_description": "On the far side of the bridge, a line of armored figures stand silent. Tin Fox growls mechanically. The Oracle Lamp dims its light.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "Glass Diver creates a mirror path across the chasm.",
      "visual_description": "The Glass Diver raises his hands, and a bridge of reflective glass shards forms beneath them, arcing over the chasm. The group steps onto it as the stone bridge crumbles behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

